CREATE OR REPLACE FUNCTION public.send_sms_hook(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  request_id bigint;
  v_url  text := 'https://thevdfcwlcqzdoybfvgs.supabase.co/functions/v1/send-phone-otp';
  v_auth text := 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InRoZXZkZmN3bGNxemRveWJmdmdzIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2MzA1NjU2MCwiZXhwIjoyMDc4NjMyNTYwfQ.U0xz7oHnUISnxzAG8ehm_gRzoOlQPucj61i2f-1FjgM';
  v_phone text;
  v_otp   text;
  v_payload jsonb;
BEGIN
  -- Extraire phone depuis tous les formats possibles
  v_phone := COALESCE(
    event->>'phone',
    event->'user'->>'phone',
    event->'data'->>'phone'
  );

  -- Extraire otp depuis tous les formats possibles
  v_otp := COALESCE(
    event->>'otp',
    event->'sms'->>'otp',
    event->'email_data'->>'token',
    event->'data'->>'otp'
  );

  -- Log pour debug (on peut supprimer apres validation)
  INSERT INTO public.sms_hook_debug_log (event_raw, phone_extracted, otp_extracted)
  VALUES (event, v_phone, v_otp);

  -- Construire un payload propre pour l'Edge Function
  v_payload := jsonb_build_object(
    'phone', v_phone,
    'otp',   v_otp
  );

  SELECT net.http_post(
    url     := v_url,
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', v_auth
    ),
    body    := v_payload
  ) INTO request_id;

  RETURN jsonb_build_object('success', true);
END;
$function$
